def unboundedKnapsack(weights, values, capacity):
    best = [0] * (capacity + 1)
    for c in range(1, capacity + 1):
        top = best[c - 1]
        for w, v in zip(weights, values):
            if w <= c and best[c - w] + v > top:
                top = best[c - w] + v
        best[c] = top
    return best[capacity]
